const { withAndroidManifest } = require('@expo/config-plugins');

// EXPO-UPDATES IS EXCLUDED FROM THIS APP, for the reason apps/integrated-app-expo/app.config.js
// gives in full: `sherlo test` splices the bundle it builds into the binary at the platform-default
// bundle path, and an Android binary with expo-updates enabled would load its JS from the updates
// runtime instead, so the CLI refuses it. The CLI Init storyline builds this app and pushes it, so
// the compiled AndroidManifest must carry ZERO `expo.modules.updates.*` meta-data entries - and
// `updates.enabled: false` alone does not achieve that (SHERLO-1744), only stripping the meta-data
// after prebuild has written it does.
const EXPO_UPDATES_META_PREFIX = 'expo.modules.updates.';
function withoutExpoUpdatesManifest(config) {
  return withAndroidManifest(config, (config) => {
    const application = config.modResults.manifest.application?.[0];
    if (application && Array.isArray(application['meta-data'])) {
      application['meta-data'] = application['meta-data'].filter(
        (item) => !item.$?.['android:name']?.startsWith(EXPO_UPDATES_META_PREFIX),
      );
    }
    return config;
  });
}

module.exports = () => {
  return {
    expo: {
      name: 'Sherlo Pre-Init Tester',
      slug: 'sherlo-pre-init-tester',
      owner: 'sherlo',
      version: '1.0.0',
      orientation: 'portrait',
      icon: './assets/icon.png',
      userInterfaceStyle: 'light',
      splash: {
        image: './assets/splash.png',
        resizeMode: 'contain',
        backgroundColor: '#ffffff'
      },
      newArchEnabled: true,
      updates: {
        enabled: false,
      },
      plugins: [withoutExpoUpdatesManifest],
      runtimeVersion: '1.0.0',
      assetBundlePatterns: ['**/*'],
      ios: {
        supportsTablet: true,
        bundleIdentifier: 'io.sherlo.preinittester',
        infoPlist: {
          ITSAppUsesNonExemptEncryption: false
        }
      },
      android: {
        adaptiveIcon: {
          foregroundImage: './assets/adaptive-icon.png',
          backgroundColor: '#ffffff'
        },
        package: 'io.sherlo.preinittester'
      },
      extra: {
        eas: {
          projectId: '0cdafdf4-6d91-4621-9966-b74e13b648cb'
        }
      }
    }
  };
};
